import{_ as t,o as s,c as r,a2 as o}from"./chunks/framework.F7eQ-ohH.js";const a="/bzygq/assets/quesion_imgs_63ffeccec77f4f60b68287bb5e524455.BTFeefL4.png",n="/bzygq/assets/quesion_imgs_35f4c3fd2a2e4d8e8f138744cbe6986b.BZ8WwIp8.png",e="/bzygq/assets/quesion_imgs_cfb022c86917402a971308dbd449ad28.C_jRQygd.png",f=JSON.parse('{"title":"什么是四则运算问题？","description":"","frontmatter":{},"headers":[],"relativePath":"行测/数量分析/4.四则运算问题.md","filePath":"行测/数量分析/4.四则运算问题.md","lastUpdated":1788883925000}'),g={name:"行测/数量分析/4.四则运算问题.md"};function i(_,p,c,d,l,h){return s(),r("div",null,[...p[0]||(p[0]=[o('<h1 id="什么是四则运算问题" tabindex="-1">什么是四则运算问题？ <a class="header-anchor" href="#什么是四则运算问题" aria-label="Permalink to &quot;什么是四则运算问题？&quot;">​</a></h1><p>四则运算主要是利用四则运算法则快速选择答案，用的方法有：尾数法、凑整法、基准数法、数学公式求解法，题目的形式可能如下所示：</p><p><strong>例：</strong> 99 + 1919 + 9999 的个位数字是（ ）</p><p><strong>解析：</strong> 9 + 9 + 9 = 27，所以答案为 7</p><p>类似上面的问题呢可能直接看不出答案，需要掌握一定的方法才能得到结果，下面我们就将给大家一一讲解行测中的所有问题和解题方法。</p><h1 id="尾数法" tabindex="-1">尾数法 <a class="header-anchor" href="#尾数法" aria-label="Permalink to &quot;尾数法&quot;">​</a></h1><p><img src="'+a+'" alt=""></p><p><strong>知识要点提示</strong>：尾数法是数学运算题解答的一个重要方法，即当四个答案全不相同时，可以采用尾数计算法，最后选择出正确答案。</p><p><strong>例 1：99 + 1919 + 9999 的个位数字是（ ）。</strong></p><p>A. 7</p><p>B. 8</p><p>C. 6</p><p>D. 9</p><p><strong>解析</strong>：9 + 9 + 9 = 27，所以答案为 7</p><p><strong>例 2：请计算（1.1）² + （1.2）² + （1.3）² + （1.4）² 的值是：</strong></p><p>A. 5.01</p><p>B. 4.32</p><p>C. 5.21</p><p>D. 6.30</p><p><strong>解析</strong>：（1.1）² 的尾数为 1，（1.2）² 的尾数为 4，（1.3）² 的尾数为 9，（1.4）² 的尾数为 6，所以最后和的尾数为 1 + 4 + 9 + 6 的和的尾数即 0，所以答案为0</p><p><strong>例 3：3 × 999 + 8 × 99 + 4 × 9 + 8 + 7 的值是：</strong></p><p>A. 4231</p><p>B.3840</p><p>C. 3841</p><p>D. 3856</p><p><strong>解析</strong>：运用尾数法。尾数和为 7 + 2 + 6 + 8 + 7 = 30，所以正确答案为0</p><p><strong>例 4：1999¹⁹⁹⁸ 的末位数字是（ ）</strong></p><p>A. 1</p><p>B. 9</p><p>C. 3</p><p>D. 7</p><p><strong>解析</strong>：考虑 9ⁿ，当 n 是奇数时，尾数是 9，当 n 是偶数时，尾数是 1，所以正确答案为 1</p><h1 id="凑整法" tabindex="-1">凑整法 <a class="header-anchor" href="#凑整法" aria-label="Permalink to &quot;凑整法&quot;">​</a></h1><p><img src="'+n+'" alt=""></p><p><strong>知识要点提示</strong>：在计算过程中，凑“10”、“100”、“1000”等凑整方法非常见。而实际上，“凑整”不仅仅是凑成一个整百、整千的数，更重要的是，凑成一个“我们需要的数”，比如：凑“7”法、凑“3”法与凑“9”法。</p><p><strong>例 1：34.16 + 47. 82 + 53. 84 + 64. 18 的值为( )</strong></p><p>解析：答案为200。四个数都由整数部分和小数部分组成，因而可以将它分成两部分来考虑。整 数部分第二、三数字之和为100,第一、四数字之和为98，即整数部分的和为198。小数部分第一、三数 字之和为1,第二、四数字之和为1，即小数部分的和为2。故两部分之和为200。</p><p><strong>例 2：8865 -721 - 306 -279 -694=( )</strong></p><p>解析：答案为 6865 。8865 - 721 -306 -279 -694 = 8865 -(721 + 279) -(306 + 694)=6865。</p><p><strong>例3：3×999 + 8×99 + 4×9 + 8 + 7的值是( )</strong></p><p>解析：答案为3840。原式=3× (1000 -1)+8× (100-1)+4 × (10-1)+8 + 7 = 3000-3 + 800-8 + 40-4 + 8 + 7 = 3840</p><h1 id="基准数法" tabindex="-1">基准数法 <a class="header-anchor" href="#基准数法" aria-label="Permalink to &quot;基准数法&quot;">​</a></h1><p><img src="'+e+'" alt=""></p><p><strong>知识要点提示</strong>：所谓“基准数法”，就是将彼此接近的数相加时，可选择其中一个数作为基准数，再找出每个数与这个基准数的差，大于基准数的差作为加数，小于基准数的差作为减数，把这些差累计起来，用合适的项数乘以基准数，加上累计差，就可算出结果。</p><p><strong>例：1962 + 1973 + 1981 + 1994 + 2005 =（ ）</strong></p><p>解析：以 1981 为基准数，那么（1981 - 19）+（1981 - 8）+ 1981 +（1981 + 13）+（1981 + 24）= 5 * 1981 + 24 + 13 - 8 - 19 = 9915。</p><h1 id="数学公式求解法" tabindex="-1">数学公式求解法 <a class="header-anchor" href="#数学公式求解法" aria-label="Permalink to &quot;数学公式求解法&quot;">​</a></h1><p><strong>知识要点提示</strong>：数学公式求解法是利用两数和、差平方公式、两数平方差公式以及两数立方的和、差公式求解式子，这类题就需要大家对第一部分的基础公司非常熟悉才能快速解决问题。</p><p><strong>例：33² + 9 - 198 =（ ）</strong></p><p>解析：33² + 9 - 198 = 33² - 2 * 33 * 3 + 3³ = (33 - 3)² = 30² = 900，答案是900</p>',50)])])}const b=t(g,[["render",i]]);export{f as __pageData,b as default};
